// Generated by ts-rs from the Rust types in gitvur-schema and gitvur-app.
// Do not edit by hand: run `pnpm gen:types` from app/.

export type Manifest = { 
/**
 * Always [`crate::SCHEMA_VERSION`].
 */
schemaVersion: string, projectName: string, 
/**
 * Short (7-character) SHA of `HEAD`, or [`crate::UNCOMMITTED`] when the repository
 * is not a Git checkout or has no commits.
 */
commitSha: string, 
/**
 * RFC 3339 UTC timestamp. The only non-deterministic field in the contract.
 */
generatedAt: string, extractor: ExtractorInfo, languages: Array<Language>, };

export type ExtractorInfo = { name: string, version: string, };

export type Language = "python" | "typescript";

export type Structure = { nodes: Array<Node>, edges: Array<Edge>, 
/**
 * Calls with two or more in-repo candidate targets.
 */
unresolvedCalls: Array<UnresolvedCall>, };

export type Node = { id: string, type: NodeType, name: string, 
/**
 * Absent only on the project node.
 */
parentId?: string, 
/**
 * Absent only on the project node.
 */
source?: SourceRange, 
/**
 * `sha256:<64 lowercase hex>`. Absent only on the project node.
 */
contentHash?: string, };

export type NodeType = "project" | "file" | "class" | "function";

export type UnresolvedCall = { 
/**
 * The calling function.
 */
from: string, 
/**
 * The called name as written at the call site (the last segment for `a.b.name()`).
 */
name: string, evidence: Evidence, 
/**
 * Every in-repo node the call could target; always two or more.
 */
candidates: Array<string>, };

export type Edge = { from: string, to: string, type: EdgeType, provenance: Provenance, evidence: Evidence, 
/**
 * Free-text explanation; written by the agent for `ai` edges.
 */
note?: string, };

export type EdgeType = "calls" | "depends_on" | "imports" | "references";

export type Provenance = "syntactic" | "semantic" | "ai";

export type Evidence = { 
/**
 * Path relative to the repository root, `/`-separated.
 */
file: string, 
/**
 * 1-based line number.
 */
line: number, };

export type SourceRange = { 
/**
 * Path relative to the repository root, `/`-separated.
 */
file: string, startLine: number, endLine: number, };

export type Annotations = { modules: Array<Module>, descriptions: Array<Description>, 
/**
 * Hidden relationships; every one must have `provenance: "ai"` and evidence.
 */
edges: Array<Edge>, };

export type Module = { 
/**
 * `module:<slug>`, slug matching `[a-z0-9-]+`.
 */
id: string, name: string, description: string, 
/**
 * File node IDs (`file:<relpath>`).
 */
files: Array<string>, };

export type Description = { 
/**
 * ID of the described node.
 */
id: string, text: string, 
/**
 * The node's `contentHash` when the description was written.
 */
basedOnHash: string, };

export type Report = { schemaVersion: string, 
/**
 * Copied from `manifest.json`.
 */
commitSha: string, summary: Summary, elements: Array<ElementStatus>, issues: Array<Issue>, };

export type Summary = { documented: number, stale: number, undocumented: number, errors: number, warnings: number, };

export type ElementStatus = { id: string, status: Status, 
/**
 * Set only when `status` is `stale`: a direct child of this element is stale.
 */
childChanged?: boolean, 
/**
 * Set only when `status` is `stale`: the element's own text (outside its direct
 * children) changed. See the validator README for how this is determined.
 */
selfChanged?: boolean, };

export type Status = "documented" | "stale" | "undocumented";

export type Issue = { severity: Severity, 
/**
 * Stable kebab-case identifier, e.g. `dangling-ref`.
 */
code: string, message: string, 
/**
 * The element the issue is about, when there is one.
 */
id?: string, };

export type Severity = "error" | "warning";

export type RepoBundle = { 
/**
 * Canonical absolute path of the repository root.
 */
root: string, manifest: Manifest, structure: Structure, annotations: Annotations | null, report: Report | null, warnings: Array<AppWarning>, };

export type AppWarning = { code: WarningCode, message: string, };

export type WarningCode = "annotations-missing" | "annotations-invalid" | "report-missing" | "report-invalid" | "report-stale";

export type AppError = { code: ErrorCode, message: string, detail?: string, };

export type ErrorCode = "not-a-directory" | "no-gitvur" | "schema-invalid" | "path-escape" | "io" | "index-failed";

export type SourceSlice = { file: string, 
/**
 * Line number of `lines[0]`.
 */
startLine: number, lines: Array<string>, language: SourceLanguage, };

export type SourceLanguage = "python" | "typescript" | "text";

export type RecentRepo = { path: string, name: string, 
/**
 * Unix time in seconds.
 */
openedAt: number, };

export type Settings = { explorerWidth: number, inspectorWidth: number, inspectorCollapsed: boolean, theme: Theme, };

export type Theme = "system" | "light" | "dark";
